list_blogs.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.blogs().listBlogs(Map.of("visibility", "open", "limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("blogs")) {
    Map<?, ?> blog = (Map<?, ?>) row;
    System.out.println(blog.get("id") + " " + blog.get("title") + " " + blog.get("date"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

